const { v5: uuidv5 } = require('uuid');
const NS = '6ba7b810-9dad-11d1-80b4-00c04fd430c8';
const did = (seed, label) => uuidv5(`${seed}:${label}`, NS);

const bundle = $input.first().json.body ?? $input.first().json;
const captureId = bundle.captureId;
if (!captureId) throw new Error('captureId required');

const hints = bundle.target?.matchHints?.address || {};
const address = {
  addressStreet1: hints.street1 || '',
  addressStreet2: null,
  addressCity: hints.city || '',
  addressState: hints.state || '',
  addressPostcode: hints.zip || '',
  addressCountry: 'United States',
};
const addressKey = `${address.addressStreet1}|${address.addressCity}|${address.addressState}|${address.addressPostcode}`;

const propertyId = bundle.target?.propertyId || did(addressKey || captureId, 'property');
const opportunityId = bundle.target?.opportunityId || did(captureId, 'opportunity');
const inspectionId = did(captureId, 'inspection');

const originMap = {
  DRIVE_BY: 'DRIVE_BY',
  SITE_WALK: 'WALKTHROUGH',
  PHOTO_LOG: 'WALKTHROUGH',
  VOICE_MEMO: 'DRIVE_BY',
};
const inspectionType = originMap[bundle.captureOrigin] || 'DRIVE_BY';

const oppName = address.addressStreet1
  ? `${address.addressStreet1} — Capture ${bundle.capturedAt?.slice(0,10) || ''}`
  : `Capture ${captureId.slice(0,8)}`;

const noteBody = `[RE acquisition capture pending extraction]\n\n${bundle.clientNotes || ''}`;

return [{
  json: {
    bundle,
    captureId,
    propertyId,
    opportunityId,
    inspectionId,
    inspectionType,
    address,
    oppName,
    noteBody,
    hasAudio: !!(bundle.audio?.fileId || bundle.audio?.pendingMediaId),
  },
}];
